// CDK: policy encoded once in a function
function secureBucket(scope: Construct, id: string) {
  return new s3.Bucket(scope, id, {
    encryption: s3.BucketEncryption.KMS_MANAGED,
    blockPublicAccess: s3.BlockPublicAccess.BLOCK_ALL,
    enforceSSL: true,
  });
}
['logs', 'assets', 'backups'].forEach(n => secureBucket(stack, n));

