  cpu: 512, memoryLimitMiB: 1024, desiredCount: 2,
  taskImageOptions: { image: ecs.ContainerImage.fromRegistry('acme/api:1.4') },
});
table.grantReadWriteData(svc.taskDefinition.taskRole);   // L2 grant, least privilege

export class StandardBucket extends Construct {
  readonly bucket: s3.Bucket;
  constructor(scope: Construct, id: string, props: { retainDays: number }) {
    super(scope, id);
    this.bucket = new s3.Bucket(this, 'B', {
      encryption: s3.BucketEncryption.KMS_MANAGED, enforceSSL: true,
      lifecycleRules: [{ expiration: Duration.days(props.retainDays) }],
    });
    Tags.of(this).add('data-class', 'internal');
  }
}
